  const manualPortfolioGreeks=useMemo(()=>aggregateGreeks(activeLegs.map(l=>legGreeks(l,{spot:state.spot,forward:state.forward,rate:state.riskFreeRate,dividend:state.dividendYield,days:daysForLeg(l,state),model:state.model},'MANUAL',state.greekInputFormat??'KUAIQI_RAW',state.greekRawProfile))),[activeLegs,state]);
